class Solution {
    public:long long minimumTotalCost(vector<int>& nums1,vector<int>& nums2){
        unordered_map<int,int> frequency;
        long long cost=0;
        int selected=0,dominant=0,dominantCount=0;
        for(int i=0;i<(int)nums1.size();++i)if(nums1[i]==nums2[i]){
            cost+=i;
            ++selected;
            int count=++frequency[nums1[i]];
            if(count>dominantCount){
                dominantCount=count;
                dominant=nums1[i];
            }
        }
        for(int i=0;i<(int)nums1.size()&&dominantCount*2>selected;++i)if(nums1[i]!=nums2[i]&&nums1[i]!=dominant&&nums2[i]!=dominant){
            cost+=i;
            ++selected;
        }
        return dominantCount*2>selected?-1:cost;
    }
};
